mapper.select:
select s.*, t.article_title as articleTitle from blog_dispatch_article_stat s left join blog_dispatch_task t on t.id = s.task_id
and s.platform_code = #{query.platformCode}
and s.article_id = #{query.articleId}
and t.article_title like concat('%', #{query.keyword}, '%')
order by s.stat_time desc, s.id desc

select s.platform_code as platformCode, p.platform_name as platformName, count(distinct s.article_id) as articleCount, coalesce(sum(s.view_count), 0) as viewCount, coalesce(sum(s.like_count), 0) as likeCount, coalesce(sum(s.comment_count), 0) as commentCount, coalesce(sum(s.collect_count), 0) as collectCount, max(s.stat_time) as lastStatTime from blog_dispatch_article_stat s left join blog_dispatch_platform p on p.platform_code = s.platform_code
and s.platform_code = #{platformCode}
group by s.platform_code, p.platform_name order by articleCount desc
